require_once __DIR__.'/storage.php';require_once __DIR__.'/reconciler.php';require_once __DIR__.'/feature-flags.php';require_once __DIR__.'/outbox.php';
function sv_ar_reconcile_case_db(PDO $db,int $caseId,DateTimeImmutable $now,?array $flags=null): array { $case=sv_ar_fetch_case($db,$caseId);if($case===null)throw new RuntimeException("Amazon recovery case {$caseId} not found.");$events=sv_ar_fetch_events($db,$caseId);$ledger=sv_ar_fetch_ledger($db,$caseId);$snapshot=sv_ar_reconcile_snapshot($case,$events,$ledger,$now,[]);sv_ar_apply_snapshot($db,$caseId,$snapshot);$flags=$flags??sv_ar_feature_flags();$decision=is_array($snapshot['decision']??null)?$snapshot['decision']:['action'=>'REVIEW_REQUIRED','reason'=>'missing_decision','write_external'=>false];$action=(string)$decision['action'];$snapshot['outbox_id']=null;$snapshot['execution_mode']='none';if(!(bool)($decision['write_external']??false))return $snapshot;$key=hash('sha256',implode('|',[$caseId,$action,(string)($snapshot['eligibility_at']??''),(string)($snapshot['safe_t_id']??'')]));if(!sv_ar_action_enabled($action,$flags)){sv_ar_append_event_db($db,$caseId,['event_type'=>'SHADOW_DECISION','source'=>'system','source_id'=>'shadow:'.$key,'observed_at'=>$now->format(DATE_ATOM),'effective_at'=>$now->format(DATE_ATOM),'payload'=>['action'=>$action,'reason'=>(string)($decision['reason']??''),'flags'=>$flags]]);$snapshot['execution_mode']='shadow';return $snapshot;}$payload=['case_id'=>$caseId,'action'=>$action,'expected_case_state'=>(string)($snapshot['case_state']??''),'decision_hash'=>$key,'policy'=>$snapshot['policy']??null];$snapshot['outbox_id']=sv_ar_schedule_action_db($db,$caseId,$case,$action,$payload);$snapshot['execution_mode']='scheduled';return $snapshot; }
